from pathlib import Path
import re

# ---------- Frontend workflow ----------
p = Path('workflow.js')
s = p.read_text(encoding='utf-8')

# Keep confirmed plans internally available to the confirmed-trip modal, but hidden from the visible planner.
old = """    const plans=[...sharedState.plans].filter(plan=>!isLocked(tripForPlan(plan))).sort((a,b)=>String(b?.meta?.start||b.updatedAt||'').localeCompare(String(a?.meta?.start||a.updatedAt||'')));\n    if(!plans.length){ root.innerHTML='<div class=\"budget-empty\">No planned trip budgets yet. Create one before your next trip.</div>'; return; }\n    const a=actor();\n    root.innerHTML=plans.map(plan=>{\n      const meta=plan.meta||{}; const trip=tripForPlan(plan); const locked=isLocked(trip);"""
new = """    const plans=[...sharedState.plans].sort((a,b)=>String(b?.meta?.start||b.updatedAt||'').localeCompare(String(a?.meta?.start||a.updatedAt||'')));\n    if(!plans.length){ root.innerHTML='<div class=\"budget-empty\">No planned trip budgets yet. Create one before your next trip.</div>'; return; }\n    const visiblePlans=plans.filter(plan=>!isLocked(tripForPlan(plan)));\n    const a=actor();\n    const emptyActive=visiblePlans.length?'':'<div class=\"budget-empty\">No active trip budgets right now. Your confirmed budgets stay inside their trip pages.</div>';\n    root.innerHTML=emptyActive+plans.map(plan=>{\n      const meta=plan.meta||{}; const trip=tripForPlan(plan); const locked=isLocked(trip);"""
if old not in s:
    raise SystemExit('Visible-plan block not found; refusing frontend patch')
s = s.replace(old, new, 1)

# Helpers for partial actuals.
anchor = """  function variance(budget,actual){\n    if(budget===''||budget==null) return {text:'Budget not set',cls:''};\n    if(actual===''||actual==null) return {text:'Actual spend not logged yet',cls:''};\n    const d=n(budget)-n(actual);\n    if(Math.abs(d)<.01) return {text:'Exactly on budget',cls:'under'};\n    return d>0 ? {text:`${money(d)} under budget`,cls:'under'} : {text:`${money(Math.abs(d))} over budget`,cls:'over'};\n  }\n"""
insert = anchor + """\n  function partialSummary(partial){\n    if(!partial)return '';\n    const parts=[];\n    if(partial.accom!==''&&partial.accom!=null)parts.push(`Accommodation ${money(partial.accom)}`);\n    if(partial.travel!==''&&partial.travel!=null)parts.push(`Flights / Train ${money(partial.travel)}`);\n    return parts.join(' · ');\n  }\n\n  function hasPartial(partial){\n    return !!partialSummary(partial);\n  }\n"""
if anchor not in s:
    raise SystemExit('variance() anchor not found')
s = s.replace(anchor, insert, 1)

# Add partial data to budget cards and make confirmed cards invisible but parseable by ui.js.
old = """      const pBudget=plan?.budgets?.Principessa??''; const qBudget=plan?.budgets?.Principe??'';\n      const pActual=trip?.submissions?.Principessa?.paid??''; const qActual=trip?.submissions?.Principe?.paid??'';\n      const pv=variance(pBudget,pActual), qv=variance(qBudget,qActual);\n      const bothBudgets=pBudget!==''&&qBudget!==''; const bothActual=pActual!==''&&qActual!=='';\n      const totalVar=bothBudgets&&bothActual?variance(n(pBudget)+n(qBudget),n(pActual)+n(qActual)):{text:bothBudgets?'Waiting for both actual spends':'Waiting for both budgets',cls:''};\n      const ownBudget=plan?.budgets?.[a]??''; const ownSub=trip?.submissions?.[a]||null;\n      const status=trip?'Trip expenses in progress':'Waiting for the trip';\n      const combinedPlanned=bothBudgets ? money(n(pBudget)+n(qBudget)) : 'Waiting for both budgets';"""
new = """      const pBudget=plan?.budgets?.Principessa??''; const qBudget=plan?.budgets?.Principe??'';\n      const pActual=trip?.submissions?.Principessa?.paid??''; const qActual=trip?.submissions?.Principe?.paid??'';\n      const pPartial=plan?.partials?.Principessa||null; const qPartial=plan?.partials?.Principe||null;\n      const pEarly=partialSummary(pPartial), qEarly=partialSummary(qPartial);\n      const pv=variance(pBudget,pActual), qv=variance(qBudget,qActual);\n      const bothBudgets=pBudget!==''&&qBudget!==''; const bothActual=pActual!==''&&qActual!=='';\n      const totalVar=bothBudgets&&bothActual?variance(n(pBudget)+n(qBudget),n(pActual)+n(qActual)):{text:bothBudgets?'Waiting for both actual spends':'Waiting for both budgets',cls:''};\n      const ownBudget=plan?.budgets?.[a]??''; const ownSub=trip?.submissions?.[a]||null;\n      const ownPartial=plan?.partials?.[a]||null; const ownStarted=hasPartial(ownPartial);\n      const anyPartial=hasPartial(pPartial)||hasPartial(qPartial);\n      const status=trip?'Trip expenses in progress':anyPartial?'Some expenses logged':'Waiting for the trip';\n      const combinedPlanned=bothBudgets ? money(n(pBudget)+n(qBudget)) : 'Waiting for both budgets';"""
if old not in s:
    raise SystemExit('Budget card variables not found')
s = s.replace(old, new, 1)

old = """      return `<article class=\"budget-plan-card\" data-v5-plan=\"${esc(plan.id)}\"><div class=\"budget-plan-top\"><div><span class=\"trip-country\">${esc(locationLabel(meta))}</span><h3>${esc(meta.city||locationLabel(meta))}</h3><p>${fmtDate(meta.start)}–${fmtDate(meta.end)}</p></div><span class=\"budget-plan-status ${trip?'live':''}\">${esc(status)}</span></div><div class=\"v5-reference\"><span>Combined planned budget</span><strong>${esc(combinedPlanned)}</strong></div><div class=\"budget-person-grid\"><div class=\"budget-person ${pv.cls}\"><span>Principessa</span><strong>${pBudget===''?'No budget':money(pBudget)}</strong><small>${esc(pv.text)}${pActual!==''?` · actual ${money(pActual)}`:''}</small></div><div class=\"budget-person ${qv.cls}\"><span>Principe</span><strong>${qBudget===''?'No budget':money(qBudget)}</strong><small>${esc(qv.text)}${qActual!==''?` · actual ${money(qActual)}`:''}</small></div></div><div class=\"budget-total-check ${totalVar.cls}\"><span>Combined</span><strong>${esc(totalVar.text)}</strong></div><div class=\"budget-plan-actions\">${a?`<button class=\"btn ghost\" type=\"button\" data-v5-own-budget>${ownBudget===''?'Add my budget':'Edit my budget'}</button>`:''}${a&&!locked&&ownBudget!==''?`<button class=\"btn primary\" type=\"button\" data-v5-actual>${ownSub?'Edit my actual expenses':'Log actual expenses'}</button>`:''}${trip?'<button class=\"btn ghost\" type=\"button\" data-v5-open-trip>Open trip</button>':''}</div></article>`;"""
new = """      return `<article class=\"budget-plan-card ${locked?'hidden':''}\" data-v5-plan=\"${esc(plan.id)}\"><div class=\"budget-plan-top\"><div><span class=\"trip-country\">${esc(locationLabel(meta))}</span><h3>${esc(meta.city||locationLabel(meta))}</h3><p>${fmtDate(meta.start)}–${fmtDate(meta.end)}</p></div><span class=\"budget-plan-status ${trip||anyPartial?'live':''}\">${esc(status)}</span></div><div class=\"v5-reference\"><span>Combined planned budget</span><strong>${esc(combinedPlanned)}</strong></div><div class=\"budget-person-grid\"><div class=\"budget-person ${pv.cls}\"><span>Principessa</span><strong>${pBudget===''?'No budget':money(pBudget)}</strong><small>${esc(pv.text)}${pActual!==''?` · actual ${money(pActual)}`:''}${pEarly?` · saved early: ${esc(pEarly)}`:''}</small></div><div class=\"budget-person ${qv.cls}\"><span>Principe</span><strong>${qBudget===''?'No budget':money(qBudget)}</strong><small>${esc(qv.text)}${qActual!==''?` · actual ${money(qActual)}`:''}${qEarly?` · saved early: ${esc(qEarly)}`:''}</small></div></div><div class=\"budget-total-check ${totalVar.cls}\"><span>Combined</span><strong>${esc(totalVar.text)}</strong></div><div class=\"budget-plan-actions\">${a&&!ownSub&&!ownStarted?`<button class=\"btn ghost\" type=\"button\" data-v5-own-budget>${ownBudget===''?'Add my budget':'Edit my budget'}</button>`:a&&(ownSub||ownStarted)?'<span class=\"budget-locked-note\">Your planned budget is locked because you already started logging actual expenses.</span>':''}${a&&!locked&&ownBudget!==''?`<button class=\"btn primary\" type=\"button\" data-v5-actual>${ownSub?'Edit my actual expenses':ownStarted?'Continue actual expenses':'Log actual expenses'}</button>`:''}${trip?'<button class=\"btn ghost\" type=\"button\" data-v5-open-trip>Open trip</button>':''}</div></article>`;"""
if old not in s:
    raise SystemExit('Budget card markup not found')
s = s.replace(old, new, 1)

s = s.replace("$('[data-v5-actual]',card)?.addEventListener('click',()=>startPlanActual(id));", "$('[data-v5-actual]',card)?.addEventListener('click',()=>startActualChoice(id));", 1)
s = s.replace("$$('[data-v5-plan-actual]').forEach(btn=>btn.addEventListener('click',()=>startPlanActual(btn.dataset.v5PlanActual)));", "$$('[data-v5-plan-actual]').forEach(btn=>btn.addEventListener('click',()=>startActualChoice(btn.dataset.v5PlanActual)));", 1)

# Insert the partial/full choice and partial mini-flow before the existing full actual flow.
anchor = """  function startPlanActual(planId){\n    const plan=planById(planId); const a=actor(); if(!plan||!a)return;\n    const trip=tripForPlan(plan); const existing=trip?.submissions?.[a]||{};\n    activeFlow={\n      type:'actual', planId, index:0, otherFlow:null,\n      draft:{accom:'',groceries:'',eat:'',travel:'',fuel:'',tolls:'',other:'',otherNote:'',paid:'',uncertain:{},...existing,uncertain:{...(existing.uncertain||{})}}\n    };\n    closeBudgetModal();\n    document.querySelector('.tab[data-sheet=\"log\"]')?.click();\n    renderActualFlow();\n    $('#wizardCard')?.scrollIntoView({behavior:'smooth',block:'center'});\n  }\n"""
replacement = """  function startActualChoice(planId){\n    const plan=planById(planId); const a=actor(); if(!plan||!a)return;\n    if(sharedState.version<6){ startPlanActual(planId); return; }\n    const partial=plan?.partials?.[a]||null;\n    const saved=partialSummary(partial);\n    const content=`${saved?`<div class=\"v5-reference\"><span>Already saved for later</span><strong>${esc(saved)}</strong></div>`:''}<div class=\"v5-choice-stack\"><button class=\"trip-pick\" type=\"button\" data-v5-actual-mode=\"full\"><span class=\"pick-icon\">✓</span><div><strong>Log everything now</strong><small>Use the normal full trip-expense wizard.</small></div></button><button class=\"trip-pick\" type=\"button\" data-v5-actual-mode=\"partial\"><span class=\"pick-icon\">＋</span><div><strong>Log some expenses now</strong><small>Save accommodation and/or Flights / Train now, then finish the rest later.</small></div></button></div>`;\n    showOverlay('ACTUAL EXPENSES',12,'How much do you want to log now?','You can record early bookings now without completing the whole trip.',content);\n    $('[data-v5-actual-mode=\"full\"]')?.addEventListener('click',()=>startPlanActual(planId));\n    $('[data-v5-actual-mode=\"partial\"]')?.addEventListener('click',()=>startPartialActual(planId));\n  }\n\n  function startPartialActual(planId){\n    const plan=planById(planId); const a=actor(); if(!plan||!a)return;\n    const existing=plan?.partials?.[a]||{};\n    activeFlow={type:'partial',planId,stage:'choose',key:'',draft:{accom:existing.accom??'',travel:existing.travel??'',uncertain:{...(existing.uncertain||{})}}};\n    closeBudgetModal();\n    document.querySelector('.tab[data-sheet=\"log\"]')?.click();\n    renderPartialActual();\n    $('#wizardCard')?.scrollIntoView({behavior:'smooth',block:'center'});\n  }\n\n  function renderPartialActual(){\n    const f=activeFlow; if(!f||f.type!=='partial')return;\n    const plan=planById(f.planId); if(!plan)return closeOverlay();\n    const saved=partialSummary(f.draft);\n    if(f.stage==='choose'){\n      const content=`${saved?`<div class=\"v5-reference\"><span>Saved in this session</span><strong>${esc(saved)}</strong></div>`:''}<div class=\"v5-choice-stack\"><button class=\"trip-pick\" type=\"button\" data-v5-partial-key=\"accom\"><span class=\"pick-icon\">⌂</span><div><strong>Accommodation</strong><small>${f.draft.accom!==''?`Currently ${money(f.draft.accom)}`:'Add accommodation cost'}</small></div></button><button class=\"trip-pick\" type=\"button\" data-v5-partial-key=\"travel\"><span class=\"pick-icon\">✈</span><div><strong>Flights / Train</strong><small>${f.draft.travel!==''?`Currently ${money(f.draft.travel)}`:'Add flight or train cost'}</small></div></button></div>${saved?'<div class=\"v5-actions\"><button class=\"btn ghost\" type=\"button\" data-v5-partial-cancel>Cancel</button><button class=\"btn primary big\" type=\"button\" data-v5-partial-save>Save for later</button></div>':''}`;\n      showOverlay('EARLY EXPENSES',24,'What do you want to log?','Choose accommodation or Flights / Train. You can add the other one afterward.',content);\n      $$('[data-v5-partial-key]').forEach(btn=>btn.addEventListener('click',()=>{f.key=btn.dataset.v5PartialKey;f.stage='amount';renderPartialActual();}));\n      $('[data-v5-partial-cancel]')?.addEventListener('click',closeOverlay);\n      $('[data-v5-partial-save]')?.addEventListener('click',savePartialActual);\n      return;\n    }\n    if(f.stage==='more'){\n      const content=`<div class=\"v5-reference\"><span>Saved so far</span><strong>${esc(saved||'—')}</strong></div><div class=\"v5-choice-stack\"><button class=\"trip-pick\" type=\"button\" data-v5-partial-more=\"yes\"><span class=\"pick-icon\">＋</span><div><strong>Yes, log something else</strong><small>Add or update Accommodation or Flights / Train.</small></div></button><button class=\"trip-pick\" type=\"button\" data-v5-partial-more=\"no\"><span class=\"pick-icon\">✓</span><div><strong>No, that’s all for now</strong><small>Save these expenses and finish the trip later.</small></div></button></div>`;\n      showOverlay('EARLY EXPENSES',72,'Anything else to log now?','Your entries stay attached to this budgeted trip until you finish the full expenses.',content);\n      $('[data-v5-partial-more=\"yes\"]')?.addEventListener('click',()=>{f.stage='choose';f.key='';renderPartialActual();});\n      $('[data-v5-partial-more=\"no\"]')?.addEventListener('click',savePartialActual);\n      return;\n    }\n    const key=f.key; const label=MONEY_LABELS[key]; const uncertain=!!f.draft?.uncertain?.[key];\n    const pot=key==='accom'?`<div class=\"v5-reference\" id=\"v5JointPot\"><span>20% available from your joint pot</span><strong>${money(n(f.draft.accom)*.20)}</strong><small>This is informational only; it does not change the accommodation expense.</small></div>`:'';\n    const content=`<div class=\"money-input-wrap\"><span>€</span><input id=\"v5PartialAmount\" class=\"big-input money-field\" inputmode=\"decimal\" value=\"${esc(String(f.draft[key]??''))}\" placeholder=\"0.00\"></div><div class=\"certainty-row\"><button class=\"certainty ${!uncertain?'active':''}\" type=\"button\" data-v5-partial-cert=\"exact\">Exact</button><button class=\"certainty ${uncertain?'active':''}\" type=\"button\" data-v5-partial-cert=\"estimate\">Not sure · estimate</button></div>${pot}<div class=\"v5-actions\"><button class=\"btn ghost\" type=\"button\" data-v5-partial-back>Back</button><button class=\"btn primary big\" type=\"button\" data-v5-partial-next>Next</button></div>`;\n    showOverlay('EARLY EXPENSES',48,`How much was ${label.toLowerCase()}?`,`Budgeted trip: ${plan.meta?.city||locationLabel(plan.meta)} · ${fmtDate(plan.meta?.start)}–${fmtDate(plan.meta?.end)}`,content);\n    const input=$('#v5PartialAmount');\n    input?.addEventListener('input',()=>{f.draft[key]=input.value;if(key==='accom'){const strong=$('#v5JointPot strong');if(strong)strong.textContent=money(n(input.value)*.20);}});\n    setTimeout(()=>input?.focus(),0);\n    $$('[data-v5-partial-cert]').forEach(btn=>btn.addEventListener('click',()=>{f.draft.uncertain={...(f.draft.uncertain||{})};f.draft.uncertain[key]=btn.dataset.v5PartialCert==='estimate';renderPartialActual();}));\n    $('[data-v5-partial-back]')?.addEventListener('click',()=>{f.stage='choose';renderPartialActual();});\n    $('[data-v5-partial-next]')?.addEventListener('click',()=>{const value=String(f.draft[key]??'').trim();if(!value||!Number.isFinite(Number(value.replace(',','.')))){toast('Enter a valid amount first','warn');return;}f.stage='more';renderPartialActual();});\n  }\n\n  async function savePartialActual(){\n    const f=activeFlow; if(!f||f.type!=='partial')return;\n    if(!hasPartial(f.draft)){toast('Add at least one expense first','warn');return;}\n    const btn=$('[data-v5-partial-save],[data-v5-partial-more=\"no\"]'); if(btn)btn.disabled=true;\n    try{\n      await post('savePlanPartial',{planId:f.planId,partial:{accom:f.draft.accom,travel:f.draft.travel,uncertain:{...(f.draft.uncertain||{})}}});\n      closeOverlay(); toast('Saved. You can finish the rest later.');\n      setTimeout(refreshState,750);\n    }catch(err){toast(err.message||'Could not save early expenses','warn');if(btn)btn.disabled=false;}\n  }\n\n  function startPlanActual(planId){\n    const plan=planById(planId); const a=actor(); if(!plan||!a)return;\n    const trip=tripForPlan(plan); const existing=trip?.submissions?.[a]||{}; const partial=plan?.partials?.[a]||{};\n    activeFlow={\n      type:'actual', planId, index:0, otherFlow:null,\n      draft:{accom:'',groceries:'',eat:'',travel:'',fuel:'',tolls:'',other:'',otherNote:'',paid:'',uncertain:{},...partial,...existing,uncertain:{...(partial.uncertain||{}),...(existing.uncertain||{})}}\n    };\n    closeBudgetModal();\n    document.querySelector('.tab[data-sheet=\"log\"]')?.click();\n    renderActualFlow();\n    $('#wizardCard')?.scrollIntoView({behavior:'smooth',block:'center'});\n  }\n"""
if anchor not in s:
    raise SystemExit('startPlanActual() anchor not found')
s = s.replace(anchor, replacement, 1)

p.write_text(s, encoding='utf-8')

# ---------- Apps Script backend ----------
p = Path('backend/Code.gs')
b = p.read_text(encoding='utf-8')
b = b.replace('version: 5', 'version: 6').replace('version:5', 'version:6')

# New plans carry per-person early expenses.
old = """          budgets: {Principessa:'', Principe:''},\n          linkedTripId: '',"""
new = """          budgets: {Principessa:'', Principe:''},\n          partials: {Principessa:null, Principe:null},\n          linkedTripId: '',"""
if old not in b:
    raise SystemExit('New-plan backend block not found')
b = b.replace(old, new, 1)

# Lock budget as soon as this person starts real spending.
old = """      if (idx >= 0) {\n        plan = sanitizePlan_(state.plans[idx]);\n        if (plan.linkedTripId) {"""
new = """      if (idx >= 0) {\n        plan = sanitizePlan_(state.plans[idx]);\n        if (plan.partials && plan.partials[actor]) {\n          throw new Error('Your planned budget is locked because you already started logging actual expenses');\n        }\n        if (plan.linkedTripId) {"""
if old not in b:
    raise SystemExit('savePlan lock block not found')
b = b.replace(old, new, 1)

# New partial-save action before the full savePlanSubmission action.
anchor = """    if (action === 'savePlanSubmission') {"""
partial_action = """    if (action === 'savePlanPartial') {\n      const planId = cleanText_(payload.planId, 80);\n      const planIdx = state.plans.findIndex(x => x.id === planId);\n      if (planIdx < 0) throw new Error('Budget plan not found');\n      const plan = sanitizePlan_(state.plans[planIdx]);\n      if (plan.linkedTripId) {\n        const linkedTrip = state.trips.find(t => t.id === plan.linkedTripId);\n        if (linkedTrip) {\n          const safeTrip = sanitizeTripRecord_(linkedTrip);\n          if (safeTrip.submissions[actor]) throw new Error('You already logged your full actual expenses');\n        }\n      }\n      const previous = plan.partials && plan.partials[actor] ? plan.partials[actor] : {};\n      const incoming = payload.partial || {};\n      const merged = Object.assign({}, previous);\n      if (incoming.accom !== undefined) merged.accom = incoming.accom;\n      if (incoming.travel !== undefined) merged.travel = incoming.travel;\n      merged.uncertain = Object.assign({}, previous.uncertain || {}, incoming.uncertain || {});\n      merged.updatedAt = new Date().toISOString();\n      const partial = sanitizePartialActual_(merged, actor);\n      if (!partial) throw new Error('Add accommodation or Flights / Train first');\n      plan.partials[actor] = partial;\n      plan.updatedAt = merged.updatedAt;\n      plan.updatedBy = actor;\n      state.plans[planIdx] = plan;\n      addAudit_(state, actor, 'savePartialActual', plan.id);\n      saveState_(state);\n      return output_({ok:true, planId:plan.id});\n    }\n\n""" + anchor
if anchor not in b:
    raise SystemExit('savePlanSubmission action anchor not found')
b = b.replace(anchor, partial_action, 1)

# Merge early saved expenses into the final submission, then clear them.
old = """      const merged = Object.assign({}, payload.submission || {}, plan.meta || {});\n      const incoming = sanitizeSubmission_(merged, actor);"""
new = """      const submitted = Object.assign({}, payload.submission || {});\n      const partial = plan.partials && plan.partials[actor] ? plan.partials[actor] : null;\n      if (partial) {\n        if (submitted.accom === '' || submitted.accom == null) submitted.accom = partial.accom;\n        if (submitted.travel === '' || submitted.travel == null) submitted.travel = partial.travel;\n        submitted.uncertain = Object.assign({}, partial.uncertain || {}, submitted.uncertain || {});\n      }\n      const merged = Object.assign({}, submitted, plan.meta || {});\n      const incoming = sanitizeSubmission_(merged, actor);"""
if old not in b:
    raise SystemExit('Full plan-submission merge block not found')
b = b.replace(old, new, 1)

old = """      plan.updatedAt = now;\n      plan.updatedBy = actor;\n      state.plans[planIdx] = plan;"""
new = """      plan.partials[actor] = null;\n      plan.updatedAt = now;\n      plan.updatedBy = actor;\n      state.plans[planIdx] = plan;"""
# This exact block appears in savePlanSubmission after trip update and is the first after our new action.
idx = b.find(old, b.find("if (action === 'savePlanSubmission')"))
if idx < 0:
    raise SystemExit('Plan finalization block not found')
b = b[:idx] + b[idx:].replace(old, new, 1)

# Sanitizers for partials and plans.
anchor = """function sanitizePlan_(plan) {\n  const budgets = plan && plan.budgets || {};"""
replacement = """function sanitizePartialActual_(partial, actor) {\n  if (!partial || typeof partial !== 'object') return null;\n  const accom = cleanMoney_(partial.accom);\n  const travel = cleanMoney_(partial.travel);\n  if (accom === '' && travel === '') return null;\n  const uncertain = cleanUncertain_(partial.uncertain);\n  return {\n    accom: accom,\n    travel: travel,\n    uncertain: uncertain,\n    updatedAt: cleanText_(partial.updatedAt, 40),\n    updatedBy: cleanActor_(partial.updatedBy || actor)\n  };\n}\n\nfunction sanitizePlan_(plan) {\n  const budgets = plan && plan.budgets || {};\n  const partials = plan && plan.partials || {};"""
if anchor not in b:
    raise SystemExit('sanitizePlan anchor not found')
b = b.replace(anchor, replacement, 1)

old = """    budgets: {\n      Principessa: cleanMoney_(budgets.Principessa),\n      Principe: cleanMoney_(budgets.Principe)\n    },\n    linkedTripId:"""
new = """    budgets: {\n      Principessa: cleanMoney_(budgets.Principessa),\n      Principe: cleanMoney_(budgets.Principe)\n    },\n    partials: {\n      Principessa: sanitizePartialActual_(partials.Principessa, 'Principessa'),\n      Principe: sanitizePartialActual_(partials.Principe, 'Principe')\n    },\n    linkedTripId:"""
if old not in b:
    raise SystemExit('sanitizePlan output block not found')
b = b.replace(old, new, 1)

p.write_text(b, encoding='utf-8')

# Cache-bust the changed workflow only.
p = Path('index.html')
i = p.read_text(encoding='utf-8')
m = re.search(r'workflow\.js\?v=(\d+)', i)
if not m:
    raise SystemExit('workflow.js script tag not found')
i = re.sub(r'workflow\.js\?v=\d+', f'workflow.js?v={int(m.group(1))+1}', i, count=1)
p.write_text(i, encoding='utf-8')

# trigger: partial-actuals-trial-v1
